CREATE TABLE IF NOT EXISTS "merchants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Registered business name. What appears on the platform invoice, not on the storefront.
	"legal_name" VARCHAR(200) NOT NULL,
	-- Where platform invoices go. Distinct from any staff login address, because finance and operations are rarely the same person.
	"billing_email" VARCHAR(320) NOT NULL,
	-- ISO 3166-1 alpha-2 country of incorporation. Drives tax treatment of the platform fee.
	"country_code" CHAR(2) NOT NULL,
	-- VAT or equivalent registration number. Null where the jurisdiction has none.
	"tax_identifier" VARCHAR(64),
	-- active | delinquent | suspended | closed. Suspending here freezes every shop the merchant owns.
	"status" VARCHAR(20) NOT NULL DEFAULT 'active',
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "merchants" IS 'The billing and legal entity behind one or more shops. It is deliberately not the tenant: a merchant can run six brands and each needs its own isolated data.';
COMMENT ON COLUMN "merchants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "merchants"."legal_name" IS 'Registered business name. What appears on the platform invoice, not on the storefront.';
COMMENT ON COLUMN "merchants"."billing_email" IS 'Where platform invoices go. Distinct from any staff login address, because finance and operations are rarely the same person.';
COMMENT ON COLUMN "merchants"."country_code" IS 'ISO 3166-1 alpha-2 country of incorporation. Drives tax treatment of the platform fee.';
COMMENT ON COLUMN "merchants"."tax_identifier" IS 'VAT or equivalent registration number. Null where the jurisdiction has none.';
COMMENT ON COLUMN "merchants"."status" IS 'active | delinquent | suspended | closed. Suspending here freezes every shop the merchant owns.';
COMMENT ON COLUMN "merchants"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "shops" (
	-- Surrogate primary key. This is the tenant key that every scoped table carries.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning merchant. Changing it is an ownership transfer and touches nothing else in the schema.
	"merchant_id" BIGINT NOT NULL,
	-- Platform subdomain segment, e.g. northern-goods. Immutable once issued because it appears in webhook payloads and app callbacks.
	"handle" VARCHAR(60) NOT NULL UNIQUE,
	-- Merchant-owned domain once verified. Null until DNS is proven.
	"custom_domain" VARCHAR(253) UNIQUE,
	-- Storefront name shown to shoppers.
	"display_name" VARCHAR(200) NOT NULL,
	-- ISO 4217 currency all prices in this shop are denominated in. A shop is single-currency; multi-currency is a presentment layer above it.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- IANA zone. Order timestamps are stored in UTC but every merchant-facing report is bucketed by this.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- trial | active | paused | frozen | closed. Frozen means unpaid: storefront down, admin still readable.
	"status" VARCHAR(20) NOT NULL DEFAULT 'trial',
	-- Shop creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Set on closure. The row is retained so data export and dispute handling still work.
	"closed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "shops" IS 'The tenant. Every row in the catalogue and order tables carries shop_id and every query is filtered by it - the one invariant the whole platform rests on.';
COMMENT ON COLUMN "shops"."id" IS 'Surrogate primary key. This is the tenant key that every scoped table carries.';
COMMENT ON COLUMN "shops"."merchant_id" IS 'Owning merchant. Changing it is an ownership transfer and touches nothing else in the schema.';
COMMENT ON COLUMN "shops"."handle" IS 'Platform subdomain segment, e.g. northern-goods. Immutable once issued because it appears in webhook payloads and app callbacks.';
COMMENT ON COLUMN "shops"."custom_domain" IS 'Merchant-owned domain once verified. Null until DNS is proven.';
COMMENT ON COLUMN "shops"."display_name" IS 'Storefront name shown to shoppers.';
COMMENT ON COLUMN "shops"."currency_code" IS 'ISO 4217 currency all prices in this shop are denominated in. A shop is single-currency; multi-currency is a presentment layer above it.';
COMMENT ON COLUMN "shops"."timezone" IS 'IANA zone. Order timestamps are stored in UTC but every merchant-facing report is bucketed by this.';
COMMENT ON COLUMN "shops"."status" IS 'trial | active | paused | frozen | closed. Frozen means unpaid: storefront down, admin still readable.';
COMMENT ON COLUMN "shops"."created_at" IS 'Shop creation time.';
COMMENT ON COLUMN "shops"."closed_at" IS 'Set on closure. The row is retained so data export and dispute handling still work.';

CREATE INDEX "idx_shops_merchant_status"
ON "shops" ("merchant_id", "status");

CREATE TABLE IF NOT EXISTS "staff_accounts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Platform-wide login identity. Unique across the platform, not per shop, so one person holds one credential however many shops they work in.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Display name shown in the admin and on activity logs.
	"full_name" VARCHAR(160) NOT NULL,
	-- Argon2id hash. Null for accounts that authenticate only through SSO.
	"password_hash" VARCHAR(255),
	-- Second factor state. Some shops require it before granting any role.
	"mfa_enabled" BOOLEAN NOT NULL DEFAULT false,
	-- Most recent successful sign-in, used to expire dormant access.
	"last_login_at" TIMESTAMPTZ,
	-- Account creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "staff_accounts" IS 'A person, not a membership. Keeping identity platform-wide is what makes an agency employee with access to nine shops one account rather than nine password resets.';
COMMENT ON COLUMN "staff_accounts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "staff_accounts"."email" IS 'Platform-wide login identity. Unique across the platform, not per shop, so one person holds one credential however many shops they work in.';
COMMENT ON COLUMN "staff_accounts"."full_name" IS 'Display name shown in the admin and on activity logs.';
COMMENT ON COLUMN "staff_accounts"."password_hash" IS 'Argon2id hash. Null for accounts that authenticate only through SSO.';
COMMENT ON COLUMN "staff_accounts"."mfa_enabled" IS 'Second factor state. Some shops require it before granting any role.';
COMMENT ON COLUMN "staff_accounts"."last_login_at" IS 'Most recent successful sign-in, used to expire dormant access.';
COMMENT ON COLUMN "staff_accounts"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "shop_staff" (
	-- Shop the access applies to.
	"shop_id" BIGINT,
	-- Person being granted access.
	"staff_account_id" BIGINT,
	-- owner | admin | staff | limited. Exactly one owner row per shop, enforced by a partial unique index in the DDL.
	"role" VARCHAR(20) NOT NULL DEFAULT 'staff',
	-- Granular grants layered on the role, e.g. ["orders.refund"]. Kept as a document because the permission vocabulary changes far faster than the schema.
	"permissions" JSONB NOT NULL DEFAULT '''[]''',
	-- Staff account that sent the invitation. Null for the founding owner, who invited nobody.
	"invited_by" BIGINT,
	-- invited | active | revoked. Revoked rows are kept so an audit shows who used to have access.
	"status" VARCHAR(16) NOT NULL DEFAULT 'invited',
	-- When the invitation was accepted. Null while pending.
	"accepted_at" TIMESTAMPTZ,
	-- When access was first granted.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("shop_id", "staff_account_id")
);

COMMENT ON TABLE "shop_staff" IS 'The membership edge, and the only place authorisation is decided. Roles on staff_accounts would make a person who is an admin of one shop an admin of all of them.';
COMMENT ON COLUMN "shop_staff"."shop_id" IS 'Shop the access applies to.';
COMMENT ON COLUMN "shop_staff"."staff_account_id" IS 'Person being granted access.';
COMMENT ON COLUMN "shop_staff"."role" IS 'owner | admin | staff | limited. Exactly one owner row per shop, enforced by a partial unique index in the DDL.';
COMMENT ON COLUMN "shop_staff"."permissions" IS 'Granular grants layered on the role, e.g. ["orders.refund"]. Kept as a document because the permission vocabulary changes far faster than the schema.';
COMMENT ON COLUMN "shop_staff"."invited_by" IS 'Staff account that sent the invitation. Null for the founding owner, who invited nobody.';
COMMENT ON COLUMN "shop_staff"."status" IS 'invited | active | revoked. Revoked rows are kept so an audit shows who used to have access.';
COMMENT ON COLUMN "shop_staff"."accepted_at" IS 'When the invitation was accepted. Null while pending.';
COMMENT ON COLUMN "shop_staff"."created_at" IS 'When access was first granted.';

CREATE INDEX "idx_shop_staff_account_status"
ON "shop_staff" ("staff_account_id", "status");

CREATE TABLE IF NOT EXISTS "platform_plans" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable machine name such as advanced. Referenced by feature gates so the marketing label can be renamed freely.
	"code" VARCHAR(40) NOT NULL UNIQUE,
	-- Customer-facing plan name.
	"name" VARCHAR(120) NOT NULL,
	-- Recurring platform fee in minor units. Integers only - never float money.
	"monthly_price_cents" INTEGER NOT NULL,
	-- ISO 4217 currency for monthly_price_cents.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Per-order platform fee in basis points. Basis points rather than a decimal keeps fee arithmetic exact.
	"transaction_fee_bps" INTEGER NOT NULL DEFAULT 0,
	-- Maximum active shop_staff rows. Null means unlimited.
	"staff_seat_limit" INTEGER,
	-- Retired plans stay for grandfathered shops but leave the pricing page.
	"active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "platform_plans" IS 'The platform-side price list, billed to the merchant per shop. It has nothing to do with what a shop charges its own shoppers.';
COMMENT ON COLUMN "platform_plans"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "platform_plans"."code" IS 'Stable machine name such as advanced. Referenced by feature gates so the marketing label can be renamed freely.';
COMMENT ON COLUMN "platform_plans"."name" IS 'Customer-facing plan name.';
COMMENT ON COLUMN "platform_plans"."monthly_price_cents" IS 'Recurring platform fee in minor units. Integers only - never float money.';
COMMENT ON COLUMN "platform_plans"."currency_code" IS 'ISO 4217 currency for monthly_price_cents.';
COMMENT ON COLUMN "platform_plans"."transaction_fee_bps" IS 'Per-order platform fee in basis points. Basis points rather than a decimal keeps fee arithmetic exact.';
COMMENT ON COLUMN "platform_plans"."staff_seat_limit" IS 'Maximum active shop_staff rows. Null means unlimited.';
COMMENT ON COLUMN "platform_plans"."active" IS 'Retired plans stay for grandfathered shops but leave the pricing page.';

CREATE TABLE IF NOT EXISTS "shop_subscriptions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Shop being billed. Billing is per shop, not per merchant, which is what makes closing one brand a clean operation.
	"shop_id" BIGINT NOT NULL,
	-- Plan currently charged.
	"plan_id" BIGINT NOT NULL,
	-- trialing | active | past_due | cancelled. past_due is what flips shops.status to frozen.
	"status" VARCHAR(20) NOT NULL DEFAULT 'trialing',
	-- Billing provider subscription id. Unique so a replayed webhook cannot create a second charge stream.
	"provider_reference" VARCHAR(120) UNIQUE,
	-- End of the free trial. Null once the shop has ever paid.
	"trial_ends_at" TIMESTAMPTZ,
	-- Start of the paid period.
	"current_period_start" TIMESTAMPTZ NOT NULL,
	-- When the shop lapses unless renewal succeeds.
	"current_period_end" TIMESTAMPTZ NOT NULL,
	-- When cancellation was requested, which is usually before the period actually ends.
	"cancelled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "shop_subscriptions" IS 'One billing relationship per shop. A merchant with six shops has six rows and six invoices, because a single merchant-level subscription cannot express six different plans.';
COMMENT ON COLUMN "shop_subscriptions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "shop_subscriptions"."shop_id" IS 'Shop being billed. Billing is per shop, not per merchant, which is what makes closing one brand a clean operation.';
COMMENT ON COLUMN "shop_subscriptions"."plan_id" IS 'Plan currently charged.';
COMMENT ON COLUMN "shop_subscriptions"."status" IS 'trialing | active | past_due | cancelled. past_due is what flips shops.status to frozen.';
COMMENT ON COLUMN "shop_subscriptions"."provider_reference" IS 'Billing provider subscription id. Unique so a replayed webhook cannot create a second charge stream.';
COMMENT ON COLUMN "shop_subscriptions"."trial_ends_at" IS 'End of the free trial. Null once the shop has ever paid.';
COMMENT ON COLUMN "shop_subscriptions"."current_period_start" IS 'Start of the paid period.';
COMMENT ON COLUMN "shop_subscriptions"."current_period_end" IS 'When the shop lapses unless renewal succeeds.';
COMMENT ON COLUMN "shop_subscriptions"."cancelled_at" IS 'When cancellation was requested, which is usually before the period actually ends.';

CREATE INDEX "idx_shop_subs_shop_status"
ON "shop_subscriptions" ("shop_id", "status");

CREATE TABLE IF NOT EXISTS "products" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning tenant. Present on every scoped table so row-level security can be one uniform policy.
	"shop_id" BIGINT NOT NULL,
	-- URL segment within the shop. Unique per shop, not globally - two shops may both sell a merino-crew-sweater.
	"handle" VARCHAR(160) NOT NULL,
	-- Product title shown on the storefront.
	"title" VARCHAR(250) NOT NULL,
	-- Long-form description, stored as sanitised HTML.
	"body_html" TEXT,
	-- Merchant-defined classification. Free text on purpose; a shared taxonomy across tenants never survives contact with real catalogues.
	"product_type" VARCHAR(120),
	-- draft | active | archived. Only active products render on the storefront.
	"status" VARCHAR(16) NOT NULL DEFAULT 'draft',
	-- Row creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Last edit; drives incremental sync for installed apps.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "products" IS 'Catalogue scoped to one tenant. Every unique constraint is composite with shop_id, which is the difference between a platform and a shop that happens to have several owners.';
COMMENT ON COLUMN "products"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "products"."shop_id" IS 'Owning tenant. Present on every scoped table so row-level security can be one uniform policy.';
COMMENT ON COLUMN "products"."handle" IS 'URL segment within the shop. Unique per shop, not globally - two shops may both sell a merino-crew-sweater.';
COMMENT ON COLUMN "products"."title" IS 'Product title shown on the storefront.';
COMMENT ON COLUMN "products"."body_html" IS 'Long-form description, stored as sanitised HTML.';
COMMENT ON COLUMN "products"."product_type" IS 'Merchant-defined classification. Free text on purpose; a shared taxonomy across tenants never survives contact with real catalogues.';
COMMENT ON COLUMN "products"."status" IS 'draft | active | archived. Only active products render on the storefront.';
COMMENT ON COLUMN "products"."created_at" IS 'Row creation time.';
COMMENT ON COLUMN "products"."updated_at" IS 'Last edit; drives incremental sync for installed apps.';

CREATE UNIQUE INDEX "uq_products_shop_handle"
ON "products" ("shop_id", "handle");
CREATE INDEX "idx_products_shop_status_updated"
ON "products" ("shop_id", "status", "updated_at");

CREATE TABLE IF NOT EXISTS "product_variants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Tenant, denormalised from the parent product so a scoped query never needs the join to enforce isolation.
	"shop_id" BIGINT NOT NULL,
	-- Parent product.
	"product_id" BIGINT NOT NULL,
	-- Merchant-assigned stock keeping unit. Unique per shop but nullable, because plenty of small catalogues never assign one.
	"sku" VARCHAR(80),
	-- Resolved option map such as {"size":"M"}. Kept denormalised for fast storefront rendering.
	"option_values" JSONB NOT NULL DEFAULT '''{}''',
	-- List price in minor units, in the shop currency.
	"price_cents" INTEGER NOT NULL,
	-- Units available. A platform keeps this simple and lets fulfilment apps own the detail.
	"inventory_quantity" INTEGER NOT NULL DEFAULT 0,
	-- Display order in the option picker.
	"position" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "product_variants" IS 'The priced, stocked thing. It carries shop_id as well as product_id so that a missing join predicate can never leak another tenant into a result set.';
COMMENT ON COLUMN "product_variants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "product_variants"."shop_id" IS 'Tenant, denormalised from the parent product so a scoped query never needs the join to enforce isolation.';
COMMENT ON COLUMN "product_variants"."product_id" IS 'Parent product.';
COMMENT ON COLUMN "product_variants"."sku" IS 'Merchant-assigned stock keeping unit. Unique per shop but nullable, because plenty of small catalogues never assign one.';
COMMENT ON COLUMN "product_variants"."option_values" IS 'Resolved option map such as {"size":"M"}. Kept denormalised for fast storefront rendering.';
COMMENT ON COLUMN "product_variants"."price_cents" IS 'List price in minor units, in the shop currency.';
COMMENT ON COLUMN "product_variants"."inventory_quantity" IS 'Units available. A platform keeps this simple and lets fulfilment apps own the detail.';
COMMENT ON COLUMN "product_variants"."position" IS 'Display order in the option picker.';

CREATE UNIQUE INDEX "uq_variants_shop_sku"
ON "product_variants" ("shop_id", "sku");
CREATE INDEX "idx_variants_product"
ON "product_variants" ("product_id");

CREATE TABLE IF NOT EXISTS "orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Tenant the order belongs to.
	"shop_id" BIGINT NOT NULL,
	-- Per-shop sequence starting at 1001. Merchants expect their own numbering, which is why this is not the surrogate id.
	"order_number" INTEGER NOT NULL,
	-- Shopper email snapshot. The platform holds no cross-shop shopper identity on purpose - a shopper belongs to the shop, not to us.
	"customer_email" VARCHAR(320) NOT NULL,
	-- pending | paid | partially_refunded | refunded | voided.
	"financial_status" VARCHAR(24) NOT NULL DEFAULT 'pending',
	-- unfulfilled | partial | fulfilled | restocked.
	"fulfillment_status" VARCHAR(24) NOT NULL DEFAULT 'unfulfilled',
	-- Currency of the totals, snapshotted from the shop in case the shop currency is later changed.
	"currency_code" CHAR(3) NOT NULL,
	-- Sum of line totals before shipping and tax.
	"subtotal_cents" INTEGER NOT NULL,
	-- Amount charged to the shopper.
	"total_cents" INTEGER NOT NULL,
	-- Fee the platform earned on this order, computed from the plan at capture time and frozen here.
	"platform_fee_cents" INTEGER NOT NULL DEFAULT 0,
	-- Delivery address snapshot. Null for a digital order.
	"shipping_address" JSONB,
	-- Checkout completion time.
	"placed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "orders" IS 'A shop order. platform_fee_cents is frozen at capture because a merchant upgrading their plan must not change what they were charged on last quarter.';
COMMENT ON COLUMN "orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "orders"."shop_id" IS 'Tenant the order belongs to.';
COMMENT ON COLUMN "orders"."order_number" IS 'Per-shop sequence starting at 1001. Merchants expect their own numbering, which is why this is not the surrogate id.';
COMMENT ON COLUMN "orders"."customer_email" IS 'Shopper email snapshot. The platform holds no cross-shop shopper identity on purpose - a shopper belongs to the shop, not to us.';
COMMENT ON COLUMN "orders"."financial_status" IS 'pending | paid | partially_refunded | refunded | voided.';
COMMENT ON COLUMN "orders"."fulfillment_status" IS 'unfulfilled | partial | fulfilled | restocked.';
COMMENT ON COLUMN "orders"."currency_code" IS 'Currency of the totals, snapshotted from the shop in case the shop currency is later changed.';
COMMENT ON COLUMN "orders"."subtotal_cents" IS 'Sum of line totals before shipping and tax.';
COMMENT ON COLUMN "orders"."total_cents" IS 'Amount charged to the shopper.';
COMMENT ON COLUMN "orders"."platform_fee_cents" IS 'Fee the platform earned on this order, computed from the plan at capture time and frozen here.';
COMMENT ON COLUMN "orders"."shipping_address" IS 'Delivery address snapshot. Null for a digital order.';
COMMENT ON COLUMN "orders"."placed_at" IS 'Checkout completion time.';

CREATE UNIQUE INDEX "uq_orders_shop_number"
ON "orders" ("shop_id", "order_number");
CREATE INDEX "idx_orders_shop_placed"
ON "orders" ("shop_id", "placed_at");

CREATE TABLE IF NOT EXISTS "apps" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Publishing partner. Platform-level, because an app exists independently of any shop.
	"developer_name" VARCHAR(200) NOT NULL,
	-- App name shown in the marketplace listing.
	"name" VARCHAR(160) NOT NULL,
	-- Marketplace URL segment.
	"slug" VARCHAR(160) NOT NULL UNIQUE,
	-- Scopes the app asks for at install, e.g. ["read_products","write_orders"]. The upper bound on what any installation may hold.
	"requested_scopes" JSONB NOT NULL DEFAULT '''[]''',
	-- OAuth callback. Validated exactly, because a loose match here is an account takeover.
	"redirect_uri" VARCHAR(500) NOT NULL,
	-- draft | listed | delisted. Delisting stops new installs without breaking existing ones.
	"status" VARCHAR(16) NOT NULL DEFAULT 'draft',
	-- Row creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "apps" IS 'The app itself, owned by a developer and shared by every shop that installs it. It is one of the few tables with no shop_id, which is exactly why it needs saying out loud.';
COMMENT ON COLUMN "apps"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "apps"."developer_name" IS 'Publishing partner. Platform-level, because an app exists independently of any shop.';
COMMENT ON COLUMN "apps"."name" IS 'App name shown in the marketplace listing.';
COMMENT ON COLUMN "apps"."slug" IS 'Marketplace URL segment.';
COMMENT ON COLUMN "apps"."requested_scopes" IS 'Scopes the app asks for at install, e.g. ["read_products","write_orders"]. The upper bound on what any installation may hold.';
COMMENT ON COLUMN "apps"."redirect_uri" IS 'OAuth callback. Validated exactly, because a loose match here is an account takeover.';
COMMENT ON COLUMN "apps"."status" IS 'draft | listed | delisted. Delisting stops new installs without breaking existing ones.';
COMMENT ON COLUMN "apps"."created_at" IS 'Row creation time.';

CREATE TABLE IF NOT EXISTS "app_installations" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Shop that installed the app.
	"shop_id" BIGINT NOT NULL,
	-- App installed.
	"app_id" BIGINT NOT NULL,
	-- Hash of the per-installation API token. Hashed rather than stored, because a leaked table must not hand over live access to every shop at once.
	"access_token_hash" VARCHAR(255) NOT NULL,
	-- Scopes actually approved by the installing staff member. Always checked at request time rather than the app requested_scopes, since an app can widen its request later.
	"granted_scopes" JSONB NOT NULL DEFAULT '''[]''',
	-- Staff account that approved the install. Null when a legacy install predates the audit trail.
	"installed_by" BIGINT,
	-- active | suspended | uninstalled. Uninstalled rows are kept so a reinstall can restore settings.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Install time.
	"installed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Set on uninstall, which is also the signal to stop delivering webhooks.
	"uninstalled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "app_installations" IS 'The tenancy boundary for integrations: one token and one scope set per shop per app, so revoking an app in one shop cannot affect the same app elsewhere.';
COMMENT ON COLUMN "app_installations"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "app_installations"."shop_id" IS 'Shop that installed the app.';
COMMENT ON COLUMN "app_installations"."app_id" IS 'App installed.';
COMMENT ON COLUMN "app_installations"."access_token_hash" IS 'Hash of the per-installation API token. Hashed rather than stored, because a leaked table must not hand over live access to every shop at once.';
COMMENT ON COLUMN "app_installations"."granted_scopes" IS 'Scopes actually approved by the installing staff member. Always checked at request time rather than the app requested_scopes, since an app can widen its request later.';
COMMENT ON COLUMN "app_installations"."installed_by" IS 'Staff account that approved the install. Null when a legacy install predates the audit trail.';
COMMENT ON COLUMN "app_installations"."status" IS 'active | suspended | uninstalled. Uninstalled rows are kept so a reinstall can restore settings.';
COMMENT ON COLUMN "app_installations"."installed_at" IS 'Install time.';
COMMENT ON COLUMN "app_installations"."uninstalled_at" IS 'Set on uninstall, which is also the signal to stop delivering webhooks.';

CREATE UNIQUE INDEX "uq_installations_shop_app"
ON "app_installations" ("shop_id", "app_id");
CREATE INDEX "idx_installations_app_status"
ON "app_installations" ("app_id", "status");

CREATE TABLE IF NOT EXISTS "webhook_subscriptions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Installation that owns this subscription. Deleting the installation must delete these, or the platform keeps posting to an app that was removed.
	"installation_id" BIGINT NOT NULL,
	-- Event name such as orders/create or products/update.
	"topic" VARCHAR(80) NOT NULL,
	-- HTTPS destination. Verified on creation to belong to the app domain.
	"endpoint_url" VARCHAR(500) NOT NULL,
	-- Payload version pinned at subscription time, so a platform upgrade does not silently reshape an app payload.
	"api_version" VARCHAR(20) NOT NULL,
	-- HMAC signing key for the delivery signature, distinct from the access token so rotating one does not invalidate the other.
	"secret" VARCHAR(128) NOT NULL,
	-- Cleared automatically after sustained delivery failure.
	"active" BOOLEAN NOT NULL DEFAULT true,
	-- Subscription time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "webhook_subscriptions" IS 'One subscription per installation per topic. Pinning api_version here is what lets the platform ship a breaking payload change without a coordinated flag day.';
COMMENT ON COLUMN "webhook_subscriptions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "webhook_subscriptions"."installation_id" IS 'Installation that owns this subscription. Deleting the installation must delete these, or the platform keeps posting to an app that was removed.';
COMMENT ON COLUMN "webhook_subscriptions"."topic" IS 'Event name such as orders/create or products/update.';
COMMENT ON COLUMN "webhook_subscriptions"."endpoint_url" IS 'HTTPS destination. Verified on creation to belong to the app domain.';
COMMENT ON COLUMN "webhook_subscriptions"."api_version" IS 'Payload version pinned at subscription time, so a platform upgrade does not silently reshape an app payload.';
COMMENT ON COLUMN "webhook_subscriptions"."secret" IS 'HMAC signing key for the delivery signature, distinct from the access token so rotating one does not invalidate the other.';
COMMENT ON COLUMN "webhook_subscriptions"."active" IS 'Cleared automatically after sustained delivery failure.';
COMMENT ON COLUMN "webhook_subscriptions"."created_at" IS 'Subscription time.';

CREATE UNIQUE INDEX "uq_webhook_subs_install_topic"
ON "webhook_subscriptions" ("installation_id", "topic");

CREATE TABLE IF NOT EXISTS "webhook_deliveries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Subscription being delivered to.
	"subscription_id" BIGINT NOT NULL,
	-- Idempotency key sent in the header. Unique per subscription so an app can safely ignore a duplicate it has already processed.
	"event_id" VARCHAR(64) NOT NULL,
	-- Attempt number. Retries append rows rather than overwriting, so a flaky endpoint leaves a visible history.
	"attempt" INTEGER NOT NULL DEFAULT 1,
	-- Serialised payload size, kept for quota accounting without storing the body forever.
	"payload_bytes" INTEGER NOT NULL,
	-- HTTP status returned. Null when the request timed out or DNS failed.
	"response_status" INTEGER,
	-- Round-trip time, used to identify apps that slow the whole fan-out.
	"duration_ms" INTEGER,
	-- pending | delivered | failed | dropped. Dropped means the retry budget was exhausted.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Scheduled time of the next attempt. Null once the delivery is terminal, which makes the retry queue a simple index scan.
	"next_retry_at" TIMESTAMPTZ,
	-- When the attempt was made.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "webhook_deliveries" IS 'One row per attempt, not per event. Without the attempt history a failing integration looks identical to a healthy one that happened to be slow.';
COMMENT ON COLUMN "webhook_deliveries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "webhook_deliveries"."subscription_id" IS 'Subscription being delivered to.';
COMMENT ON COLUMN "webhook_deliveries"."event_id" IS 'Idempotency key sent in the header. Unique per subscription so an app can safely ignore a duplicate it has already processed.';
COMMENT ON COLUMN "webhook_deliveries"."attempt" IS 'Attempt number. Retries append rows rather than overwriting, so a flaky endpoint leaves a visible history.';
COMMENT ON COLUMN "webhook_deliveries"."payload_bytes" IS 'Serialised payload size, kept for quota accounting without storing the body forever.';
COMMENT ON COLUMN "webhook_deliveries"."response_status" IS 'HTTP status returned. Null when the request timed out or DNS failed.';
COMMENT ON COLUMN "webhook_deliveries"."duration_ms" IS 'Round-trip time, used to identify apps that slow the whole fan-out.';
COMMENT ON COLUMN "webhook_deliveries"."status" IS 'pending | delivered | failed | dropped. Dropped means the retry budget was exhausted.';
COMMENT ON COLUMN "webhook_deliveries"."next_retry_at" IS 'Scheduled time of the next attempt. Null once the delivery is terminal, which makes the retry queue a simple index scan.';
COMMENT ON COLUMN "webhook_deliveries"."created_at" IS 'When the attempt was made.';

CREATE UNIQUE INDEX "uq_deliveries_sub_event_attempt"
ON "webhook_deliveries" ("subscription_id", "event_id", "attempt");
CREATE INDEX "idx_deliveries_retry_queue"
ON "webhook_deliveries" ("status", "next_retry_at");

